require 'json'

t = input["text"].to_s.strip
# remove ```json ... ``` or ``` ... ``` wrappers if Claude adds them
t = t.sub(/\A```json\s*/i, "").sub(/\A```\s*/, "").sub(/```\s*\z/, "").strip

# grab the JSON array substring if there's stray prose
if t[0] != "["
  s = t.index("[")
  e = t.rindex("]")
  t = t[s..e] if s && e && e > s
end

parsed = JSON.parse(t) rescue []

# normalize each object so downstream mapping never breaks on missing keys
results = parsed.map do |a|
  {
    "gongCallId" => a["gongCallId"].to_s,
    "reason"     => a["reason"].to_s,
    "formDiscrepancies" => {
      "found"  => !!(a.dig("formDiscrepancies","found")),
      "detail" => a.dig("formDiscrepancies","detail")
    },
    "missingDocuments" => {
      "found" => !!(a.dig("missingDocuments","found")),
      "items" => (a.dig("missingDocuments","items") || [])
    },
    "complexCase" => {
      "found"  => !!(a.dig("complexCase","found")),
      "detail" => a.dig("complexCase","detail")
    },
    "demoNeeded"        => !!a["demoNeeded"],
    "screenSharingUsed" => !!a["screenSharingUsed"],
    "residentialProxyJustification" => {
      "explained" => !!(a.dig("residentialProxyJustification","explained")),
      "reason"    => a.dig("residentialProxyJustification","reason")
    },
    "specialPermissionsDiscussed" => {
      "found"  => !!(a.dig("specialPermissionsDiscussed","found")),
      "detail" => a.dig("specialPermissionsDiscussed","detail")
    }
  }
end

{ "results" => results, "count" => results.length }
